import os,glob,re,json,collections
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def solve(di):
    H,W=len(di),len(di[0])
    colors=set(v for r in di for v in r)
    bg=max(colors,key=lambda v: sum(r.count(v) for r in di))
    others=colors-{bg}
    c1,c2=list(others)
    out=[row[:] for row in di]
    seedset={(i,j) for i in range(H) for j in range(W) if di[i][j] in others}
    q=collections.deque(seedset)
    while q:
        a=q.popleft(); col=out[a]
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a[0]+dr,a[1]+dc
            if 0<=x<H and 0<=y<W and (x,y) not in seedset and di[x][y]==bg:
                newcol = c2 if col==c1 else c1
                out[x][y]=newcol; q.append((x,y)); seedset.add((x,y))
    return out

for name in ('Demo pair 1','Demo pair 2'):
    pred=solve(G[name+' input']); exp=G[name+' output']
    diffs=[(i,j,pred[i][j],exp[i][j]) for i in range(len(pred)) for j in range(len(pred[0])) if pred[i][j]!=exp[i][j]]
    print(name,'diffs:',len(diffs), diffs[:15])

