    out=[row[:] for row in I]
    walls={(i,j) for i in range(H) for j in range(W) if I[i][j]==wall}
    # union component of walls reachable from any seed
    allw=set(seeds)
    while True:
        new=False
        for s in list(allw):
            i,j=s
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni,nj=i+di,j+dj
                if (ni,nj) in walls and (ni,nj) not in allw:
                    allw.add((ni,nj)); new=True
        if not new: break
    # colors by parity: determine which marker color sits on which parity
    par={}
    for i,j,c in seeds:
        par[(i+j)%2]=c
    for (i,j) in allw:
